"""Python code parser using Jedi + Python AST.

Extracts functions, classes, methods, imports, signatures, docstrings,
and call relationships from .py files with 95%+ accuracy.
"""

import ast
import logging
import textwrap
from pathlib import Path
from typing import Optional

try:
    import jedi
except ImportError:
    jedi = None  # type: ignore[assignment]

from src.parsers.base import CallEdge, CodeParser, Dependency, ParsedEntity

logger = logging.getLogger(__name__)


def _get_qualified_name(module_name: str, node_name: str, class_name: Optional[str] = None) -> str:
    if class_name:
        return f"{module_name}.{class_name}.{node_name}"
    return f"{module_name}.{node_name}"


def _extract_signature(node: ast.FunctionDef | ast.AsyncFunctionDef) -> str:
    """Build a human-readable signature string from an AST function node."""
    args = node.args
    params: list[str] = []

    # positional args (with potential defaults)
    defaults_offset = len(args.args) - len(args.defaults)
    for i, arg in enumerate(args.args):
        annotation = ast.unparse(arg.annotation) if arg.annotation else None
        param = arg.arg
        if annotation:
            param = f"{param}: {annotation}"
        default_idx = i - defaults_offset
        if default_idx >= 0:
            param = f"{param} = {ast.unparse(args.defaults[default_idx])}"
        params.append(param)

    # *args
    if args.vararg:
        annotation = ast.unparse(args.vararg.annotation) if args.vararg.annotation else None
        params.append(f"*{args.vararg.arg}" + (f": {annotation}" if annotation else ""))
    elif args.kwonlyargs:
        params.append("*")

    # keyword-only args
    kw_defaults = args.kw_defaults
    for i, arg in enumerate(args.kwonlyargs):
        annotation = ast.unparse(arg.annotation) if arg.annotation else None
        param = arg.arg
        if annotation:
            param = f"{param}: {annotation}"
        if kw_defaults[i] is not None:
            param = f"{param} = {ast.unparse(kw_defaults[i])}"
        params.append(param)

    # **kwargs
    if args.kwarg:
        annotation = ast.unparse(args.kwarg.annotation) if args.kwarg.annotation else None
        params.append(f"**{args.kwarg.arg}" + (f": {annotation}" if annotation else ""))

    return_annotation = f" -> {ast.unparse(node.returns)}" if node.returns else ""
    prefix = "async def " if isinstance(node, ast.AsyncFunctionDef) else "def "
    return f"{prefix}{node.name}({', '.join(params)}){return_annotation}"


def _extract_calls(node: ast.AST) -> list[str]:
    """Extract all call names from an AST subtree (best-effort dotted names)."""
    calls: list[str] = []
    for child in ast.walk(node):
        if isinstance(child, ast.Call):
            if isinstance(child.func, ast.Name):
                calls.append(child.func.id)
            elif isinstance(child.func, ast.Attribute):
                parts: list[str] = []
                current: ast.expr = child.func
                while isinstance(current, ast.Attribute):
                    parts.append(current.attr)
                    current = current.value
                if isinstance(current, ast.Name):
                    parts.append(current.id)
                calls.append(".".join(reversed(parts)))
    return calls


class PythonParser(CodeParser):
    """Parser for Python source files using ast + Jedi."""

    def _module_name(self, file_path: str) -> str:
        """Derive dotted module name from file path (best-effort)."""
        p = Path(file_path)
        # strip .py extension and convert slashes to dots
        parts = list(p.with_suffix("").parts)
        # drop common root segments like src/, backend/
        while parts and parts[0] in {".", "src", "backend", "app"}:
            parts.pop(0)
        return ".".join(parts) if parts else p.stem

    def parse_file(self, file_path: str) -> list[ParsedEntity]:
        """Extract all functions, classes, and methods from a Python file."""
        try:
            source = Path(file_path).read_text(encoding="utf-8", errors="replace")
        except OSError as exc:
            logger.warning("Cannot read %s: %s", file_path, exc)
            return []

        try:
            tree = ast.parse(source, filename=file_path)
        except SyntaxError as exc:
            logger.warning("Syntax error in %s: %s", file_path, exc)
            return []

        module_name = self._module_name(file_path)
        entities: list[ParsedEntity] = []

        # module-level docstring
        module_doc: Optional[str] = ast.get_docstring(tree)
        entities.append(
            ParsedEntity(
                name=module_name.split(".")[-1],
                qualified_name=module_name,
                entity_type="module",
                file_path=file_path,
                line_start=1,
                line_end=len(source.splitlines()),
                docstring=module_doc,
                imports=self._raw_imports(tree),
            )
        )

        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                docstring = ast.get_docstring(node)
                qname = f"{module_name}.{node.name}"
                base_names = [ast.unparse(b) for b in node.bases]
                class_entity = ParsedEntity(
                    name=node.name,
                    qualified_name=qname,
                    entity_type="class",
                    file_path=file_path,
                    line_start=node.lineno,
                    line_end=getattr(node, "end_lineno", node.lineno),
                    docstring=docstring,
                    calls=_extract_calls(node),
                    entity_metadata={
                        "bases": base_names,
                        "decorators": [ast.unparse(d) for d in node.decorator_list],
                    },
                )
                entities.append(class_entity)

                # methods inside the class
                for item in node.body:
                    if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        method_doc = ast.get_docstring(item)
                        method_entity = ParsedEntity(
                            name=item.name,
                            qualified_name=f"{qname}.{item.name}",
                            entity_type="method",
                            file_path=file_path,
                            line_start=item.lineno,
                            line_end=getattr(item, "end_lineno", item.lineno),
                            signature=_extract_signature(item),
                            docstring=method_doc,
                            calls=_extract_calls(item),
                            entity_metadata={
                                "class": node.name,
                                "decorators": [ast.unparse(d) for d in item.decorator_list],
                                "is_async": isinstance(item, ast.AsyncFunctionDef),
                            },
                        )
                        entities.append(method_entity)

            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                # top-level functions only (skip nested)
                parent = getattr(node, "_parent", None)
                if isinstance(parent, ast.ClassDef):
                    continue  # already handled above
                docstring = ast.get_docstring(node)
                entities.append(
                    ParsedEntity(
                        name=node.name,
                        qualified_name=f"{module_name}.{node.name}",
                        entity_type="function",
                        file_path=file_path,
                        line_start=node.lineno,
                        line_end=getattr(node, "end_lineno", node.lineno),
                        signature=_extract_signature(node),
                        docstring=docstring,
                        calls=_extract_calls(node),
                        entity_metadata={
                            "decorators": [ast.unparse(d) for d in node.decorator_list],
                            "is_async": isinstance(node, ast.AsyncFunctionDef),
                        },
                    )
                )

        # set parent references (needed for nested function detection above)
        _set_parents(tree)
        return entities

    def _raw_imports(self, tree: ast.Module) -> list[str]:
        """Return raw import strings from a parsed AST."""
        imports: list[str] = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    imports.append(alias.name)
            elif isinstance(node, ast.ImportFrom):
                module = node.module or ""
                for alias in node.names:
                    imports.append(f"{module}.{alias.name}" if module else alias.name)
        return imports

    def resolve_imports(self, file_path: str) -> list[Dependency]:
        """Resolve import statements using Jedi for cross-file resolution."""
        deps: list[Dependency] = []

        try:
            source = Path(file_path).read_text(encoding="utf-8", errors="replace")
            tree = ast.parse(source, filename=file_path)
        except (OSError, SyntaxError):
            return deps

        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    resolved = _jedi_resolve(file_path, source, node.lineno, alias.name)
                    deps.append(
                        Dependency(
                            source_file=file_path,
                            imported_name=alias.name,
                            resolved_path=resolved,
                        )
                    )
            elif isinstance(node, ast.ImportFrom):
                module = node.module or ""
                for alias in node.names:
                    full_name = f"{module}.{alias.name}" if module else alias.name
                    resolved = _jedi_resolve(file_path, source, node.lineno, full_name)
                    deps.append(
                        Dependency(
                            source_file=file_path,
                            imported_name=full_name,
                            resolved_path=resolved,
                        )
                    )

        return deps

    def get_call_graph(self, file_path: str) -> list[CallEdge]:
        """Extract caller→callee pairs from a Python file."""
        try:
            source = Path(file_path).read_text(encoding="utf-8", errors="replace")
            tree = ast.parse(source, filename=file_path)
        except (OSError, SyntaxError):
            return []

        module_name = self._module_name(file_path)
        edges: list[CallEdge] = []

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                caller_qname = f"{module_name}.{node.name}"
                for callee in _extract_calls(node):
                    edges.append(CallEdge(caller=caller_qname, callee=callee))

        return edges


def _set_parents(tree: ast.AST) -> None:
    """Annotate each AST node with a `_parent` attribute."""
    for node in ast.walk(tree):
        for child in ast.iter_child_nodes(node):
            child._parent = node  # type: ignore[attr-defined]


def _jedi_resolve(file_path: str, source: str, line: int, name: str) -> Optional[str]:
    """Try to resolve an import name to an absolute path using Jedi."""
    if jedi is None:
        return None
    try:
        script = jedi.Script(source=source, path=file_path)
        definitions = script.goto(line=line, column=0)
        for defn in definitions:
            if defn.module_path:
                return str(defn.module_path)
    except Exception:
        pass
    return None

"""TypeScript/JavaScript parser wrapping the TypeScript Compiler API via Node.js subprocess.

The Node.js script `ts_extractor/extractor.js` does the heavy lifting;
this class just calls it and unmarshals the JSON output.
"""

import json
import logging
import subprocess
from pathlib import Path
from typing import Optional

from src.parsers.base import CallEdge, CodeParser, Dependency, ParsedEntity

logger = logging.getLogger(__name__)

# Path to the Node.js extractor script (sibling directory)
_EXTRACTOR_JS = Path(__file__).parent / "ts_extractor" / "extractor.js"

# Supported extensions
SUPPORTED_EXTENSIONS = {".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"}


def _run_extractor(file_path: str) -> Optional[dict]:
    """Run the Node.js TS extractor and return parsed JSON, or None on failure."""
    if not _EXTRACTOR_JS.exists():
        logger.error("TypeScript extractor not found at %s", _EXTRACTOR_JS)
        return None

    try:
        result = subprocess.run(
            ["node", str(_EXTRACTOR_JS), file_path],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if result.returncode != 0:
            logger.warning("TS extractor failed for %s: %s", file_path, result.stderr[:200])
            return None
        return json.loads(result.stdout)
    except subprocess.TimeoutExpired:
        logger.warning("TS extractor timed out for %s", file_path)
    except json.JSONDecodeError as exc:
        logger.warning("TS extractor returned invalid JSON for %s: %s", file_path, exc)
    except FileNotFoundError:
        logger.error("'node' not found in PATH — cannot parse TypeScript files")
    except Exception as exc:
        logger.warning("TS extractor unexpected error for %s: %s", file_path, exc)
    return None


class TypeScriptParser(CodeParser):
    """Parser for TypeScript/JavaScript source files using the TS Compiler API."""

    def parse_file(self, file_path: str) -> list[ParsedEntity]:
        """Extract all code entities from a TS/JS file."""
        data = _run_extractor(file_path)
        if not data:
            return []

        entities: list[ParsedEntity] = []
        for raw in data.get("entities", []):
            entities.append(
                ParsedEntity(
                    name=raw["name"],
                    qualified_name=raw["qualified_name"],
                    entity_type=raw["entity_type"],
                    file_path=raw["file_path"],
                    line_start=raw.get("line_start", 1),
                    line_end=raw.get("line_end", 1),
                    signature=raw.get("signature"),
                    docstring=raw.get("docstring"),
                    calls=[e["callee"] for e in data.get("call_edges", [])
                           if e.get("caller") == raw["qualified_name"]],
                    imports=[imp["imported_name"] for imp in data.get("imports", [])],
                    entity_metadata=raw.get("entity_metadata", {}),
                )
            )
        return entities

    def resolve_imports(self, file_path: str) -> list[Dependency]:
        """Resolve import statements from a TS/JS file."""
        data = _run_extractor(file_path)
        if not data:
            return []

        return [
            Dependency(
                source_file=file_path,
                imported_name=imp["imported_name"],
                resolved_path=imp.get("resolved_path"),
            )
            for imp in data.get("imports", [])
        ]

    def get_call_graph(self, file_path: str) -> list[CallEdge]:
        """Extract call edges from a TS/JS file."""
        data = _run_extractor(file_path)
        if not data:
            return []

        return [
            CallEdge(caller=edge["caller"], callee=edge["callee"])
            for edge in data.get("call_edges", [])
            if edge.get("caller") and edge.get("callee")
        ]

"""DependencyAuditor — heuristic agent that parses lock files (zero LLM calls).

Reads: requirements*.txt, package-lock.json, go.sum, Cargo.lock, pom.xml
Writes: Dossier.dependencies (DependencyAnalysis)
"""

import json
import logging
import re
from pathlib import Path
from typing import Optional

from src.dossier.manager import DossierManager
from src.dossier.schema import (
    DependencyAnalysis,
    DependencyEntry,
    DependencyVulnerability,
    Severity,
)

logger = logging.getLogger(__name__)

AGENT_NAME = "dependency_auditor"


def run(repo_path: str, dossier_manager: DossierManager) -> None:
    """Parse dependency manifests and write findings to Dossier."""
    root = Path(repo_path)
    packages: list[DependencyEntry] = []

    packages.extend(_parse_requirements(root))
    packages.extend(_parse_package_json(root))
    packages.extend(_parse_go_mod(root))
    packages.extend(_parse_cargo_toml(root))

    total_vulns = sum(len(p.vulnerabilities) for p in packages)
    high_risk = [p.name for p in packages if any(
        v.severity in (Severity.CRITICAL, Severity.HIGH) for v in p.vulnerabilities
    )]

    analysis = DependencyAnalysis(
        packages=packages,
        total_vulnerabilities=total_vulns,
        high_risk_packages=high_risk,
    )
    dossier_manager.write_section("dependencies", analysis)
    dossier_manager.mark_agent_complete(AGENT_NAME)
    logger.info("DependencyAuditor: found %d packages, %d vulns", len(packages), total_vulns)


def _parse_requirements(root: Path) -> list[DependencyEntry]:
    entries: list[DependencyEntry] = []
    for req_file in root.glob("requirements*.txt"):
        try:
            for line in req_file.read_text().splitlines():
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                # Handle pinned (==), minimum (>=), ranges
                match = re.match(r"^([\w\-\.]+)\s*([>=<!~^]+.*)?$", line)
                if match:
                    name = match.group(1)
                    version = (match.group(2) or "").strip()
                    entries.append(DependencyEntry(name=name, version=version or "unknown"))
        except OSError:
            pass
    return entries


def _parse_package_json(root: Path) -> list[DependencyEntry]:
    pkg_json = root / "package.json"
    if not pkg_json.exists():
        return []
    try:
        data = json.loads(pkg_json.read_text())
        entries: list[DependencyEntry] = []
        for dep_type, is_direct in [("dependencies", True), ("devDependencies", False)]:
            for name, version in data.get(dep_type, {}).items():
                entries.append(DependencyEntry(name=name, version=version, is_direct=is_direct))
        return entries
    except Exception:
        return []


def _parse_go_mod(root: Path) -> list[DependencyEntry]:
    go_mod = root / "go.mod"
    if not go_mod.exists():
        return []
    entries: list[DependencyEntry] = []
    try:
        in_require = False
        for line in go_mod.read_text().splitlines():
            line = line.strip()
            if line.startswith("require ("):
                in_require = True
                continue
            if in_require and line == ")":
                in_require = False
                continue
            if in_require or line.startswith("require "):
                clean = line.replace("require ", "").strip()
                parts = clean.split()
                if len(parts) >= 2:
                    entries.append(DependencyEntry(name=parts[0], version=parts[1]))
    except OSError:
        pass
    return entries


def _parse_cargo_toml(root: Path) -> list[DependencyEntry]:
    cargo = root / "Cargo.toml"
    if not cargo.exists():
        return []
    entries: list[DependencyEntry] = []
    try:
        in_deps = False
        for line in cargo.read_text().splitlines():
            line = line.strip()
            if line == "[dependencies]":
                in_deps = True
                continue
            if line.startswith("[") and line != "[dependencies]":
                in_deps = False
                continue
            if in_deps and "=" in line:
                name, _, version = line.partition("=")
                entries.append(DependencyEntry(
                    name=name.strip(),
                    version=version.strip().strip('"'),
                ))
    except OSError:
        pass
    return entries

"""CIPipelineAnalyzer — parses GitHub Actions workflows and Jenkinsfiles (zero LLM)."""

import logging
import re
from pathlib import Path

import yaml

from src.dossier.manager import DossierManager
from src.dossier.schema import CIJob, CIPipeline, CIStep

logger = logging.getLogger(__name__)

AGENT_NAME = "ci_pipeline_analyzer"


def run(repo_path: str, dossier_manager: DossierManager) -> None:
    root = Path(repo_path)

    pipeline = _parse_github_actions(root)
    if not pipeline:
        pipeline = _parse_jenkinsfile(root)
    if not pipeline:
        pipeline = CIPipeline(provider="none")

    dossier_manager.write_section("ci_pipeline", pipeline)
    dossier_manager.mark_agent_complete(AGENT_NAME)
    logger.info("CIPipelineAnalyzer: provider=%s, jobs=%d", pipeline.provider, len(pipeline.jobs))


def _parse_github_actions(root: Path) -> CIPipeline | None:
    workflows_dir = root / ".github" / "workflows"
    if not workflows_dir.exists():
        return None

    jobs: list[CIJob] = []
    triggers: list[str] = []
    has_tests = has_deploy = has_lint = False

    for workflow_file in workflows_dir.glob("*.yml"):
        try:
            data = yaml.safe_load(workflow_file.read_text()) or {}
        except Exception:
            continue

        on = data.get("on") or data.get(True) or {}
        if isinstance(on, dict):
            triggers.extend(on.keys())
        elif isinstance(on, list):
            triggers.extend(on)
        elif isinstance(on, str):
            triggers.append(on)

        for job_name, job_data in (data.get("jobs") or {}).items():
            if not isinstance(job_data, dict):
                continue
            steps: list[CIStep] = []
            for step in job_data.get("steps") or []:
                step_name = step.get("name", "")
                step_uses = step.get("uses", "")
                step_run = step.get("run", "")
                steps.append(CIStep(name=step_name, command=step_run or None, uses=step_uses or None))
                lower = (step_name + step_run).lower()
                if any(kw in lower for kw in ["test", "pytest", "jest", "mocha"]):
                    has_tests = True
                if any(kw in lower for kw in ["deploy", "publish", "release"]):
                    has_deploy = True
                if any(kw in lower for kw in ["lint", "eslint", "ruff", "flake8"]):
                    has_lint = True
            jobs.append(CIJob(
                name=job_name,
                runner=job_data.get("runs-on"),
                steps=steps,
            ))

    return CIPipeline(
        provider="github_actions",
        triggers=list(set(triggers)),
        jobs=jobs,
        has_tests=has_tests,
        has_deploy=has_deploy,
        has_lint=has_lint,
    )


def _parse_jenkinsfile(root: Path) -> CIPipeline | None:
    jenkins = root / "Jenkinsfile"
    if not jenkins.exists():
        return None
    try:
        content = jenkins.read_text()
        stage_names = re.findall(r"stage\s*\(\s*['\"](.+?)['\"]\s*\)", content)
        steps = [CIStep(name=s) for s in stage_names]
        has_tests = any("test" in s.lower() for s in stage_names)
        has_deploy = any("deploy" in s.lower() for s in stage_names)
        return CIPipeline(
            provider="jenkins",
            triggers=["push"],
            jobs=[CIJob(name="pipeline", steps=steps)],
            has_tests=has_tests,
            has_deploy=has_deploy,
        )
    except OSError:
        return None

"""IaCAnalyzer — identifies IaC files (Terraform, K8s, Helm) with zero LLM calls."""

import logging
from pathlib import Path

from src.dossier.manager import DossierManager

logger = logging.getLogger(__name__)

AGENT_NAME = "iac_analyzer"

_IaC_PATTERNS = {
    "terraform": ["*.tf", "*.tfvars"],
    "kubernetes": ["*.k8s.yaml", "kubernetes/**/*.yaml", "k8s/**/*.yaml", "deploy/**/*.yaml"],
    "helm": ["Chart.yaml", "helm/**"],
    "ansible": ["playbook*.yml", "ansible/**/*.yml"],
    "pulumi": ["Pulumi.yaml"],
    "cdk": ["cdk.json"],
}


def run(repo_path: str, dossier_manager: DossierManager) -> None:
    root = Path(repo_path)
    findings: dict[str, list[str]] = {}

    for tool, patterns in _IaC_PATTERNS.items():
        matched: list[str] = []
        for pattern in patterns:
            for p in root.rglob(pattern.replace("**", "*")):
                if p.is_file():
                    matched.append(str(p.relative_to(root)))
        if matched:
            findings[tool] = matched

    # Store in Dossier extra field (no dedicated schema section for IaC yet)
    dossier_manager.write_section(
        "extra",
        {**dossier_manager.get_section("extra"), "iac": findings},
    )
    dossier_manager.mark_agent_complete(AGENT_NAME)
    logger.info("IaCAnalyzer: detected tools %s", list(findings.keys()))

"""APIContractExtractor — detects OpenAPI/Swagger, GraphQL, gRPC schemas (zero LLM)."""

import logging
import re
from pathlib import Path

from src.dossier.manager import DossierManager

logger = logging.getLogger(__name__)

AGENT_NAME = "api_contract_extractor"


def run(repo_path: str, dossier_manager: DossierManager) -> None:
    root = Path(repo_path)
    contracts: dict[str, list[str]] = {}

    # OpenAPI/Swagger
    openapi_files: list[str] = []
    for p in root.rglob("*"):
        if p.is_file() and p.suffix in {".yaml", ".yml", ".json"}:
            try:
                content = p.read_text(errors="replace")[:500]
                if "openapi" in content or "swagger" in content:
                    openapi_files.append(str(p.relative_to(root)))
            except OSError:
                pass
    if openapi_files:
        contracts["openapi"] = openapi_files

    # GraphQL
    gql_files = [str(p.relative_to(root)) for p in root.rglob("*.graphql")] + \
                [str(p.relative_to(root)) for p in root.rglob("*.gql")]
    if gql_files:
        contracts["graphql"] = gql_files

    # gRPC / Protobuf
    proto_files = [str(p.relative_to(root)) for p in root.rglob("*.proto")]
    if proto_files:
        contracts["grpc"] = proto_files

    extra = dossier_manager.get_section("extra") or {}
    dossier_manager.write_section("extra", {**extra, "api_contracts": contracts})
    dossier_manager.mark_agent_complete(AGENT_NAME)
    logger.info("APIContractExtractor: found %s contract types", list(contracts.keys()))

"""OwnershipExtractor — reads CODEOWNERS files (zero LLM calls)."""

import logging
import re
from pathlib import Path

from src.dossier.manager import DossierManager

logger = logging.getLogger(__name__)

AGENT_NAME = "ownership_extractor"


def run(repo_path: str, dossier_manager: DossierManager) -> None:
    root = Path(repo_path)
    ownership: dict[str, list[str]] = {}

    for codeowners_path in [root / "CODEOWNERS", root / ".github" / "CODEOWNERS", root / "docs" / "CODEOWNERS"]:
        if codeowners_path.exists():
            try:
                for line in codeowners_path.read_text().splitlines():
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    parts = line.split()
                    if len(parts) >= 2:
                        pattern, owners = parts[0], parts[1:]
                        ownership[pattern] = owners
            except OSError:
                pass
            break  # Only one CODEOWNERS file

    extra = dossier_manager.get_section("extra") or {}
    dossier_manager.write_section("extra", {**extra, "ownership": ownership})
    dossier_manager.mark_agent_complete(AGENT_NAME)
    logger.info("OwnershipExtractor: %d ownership patterns", len(ownership))

"""FeatureFlagMapper — detects feature flag patterns in source code (zero LLM calls)."""

import logging
import re
from pathlib import Path

from src.dossier.manager import DossierManager
from src.dossier.schema import FeatureFlag, FeatureFlagInventory

logger = logging.getLogger(__name__)

AGENT_NAME = "feature_flag_mapper"

# Patterns to detect feature flag usage
_FLAG_PATTERNS = [
    re.compile(r'(?:feature_flags?|features?|flags?)\[[\'"]([\w\-]+)[\'"]\]'),
    re.compile(r'(?:isEnabled|isFeatureEnabled|getFlag)\([\'\"]([\w\-]+)[\'\"]\)'),
    re.compile(r'FEATURE_(?:FLAG_)?(\w+)\s*='),
    re.compile(r'ENABLE_(\w+)\s*='),
]

_SKIP_DIRS = {".git", "node_modules", "__pycache__", ".venv", "dist", "build"}


def run(repo_path: str, dossier_manager: DossierManager) -> None:
    root = Path(repo_path)
    flags: dict[str, FeatureFlag] = {}

    for file_path in root.rglob("*"):
        if not file_path.is_file():
            continue
        if any(skip in file_path.parts for skip in _SKIP_DIRS):
            continue
        if file_path.suffix not in {".py", ".ts", ".tsx", ".js", ".jsx", ".go", ".rb", ".java"}:
            continue
        try:
            content = file_path.read_text(errors="replace")
        except OSError:
            continue

        rel = str(file_path.relative_to(root))
        for pattern in _FLAG_PATTERNS:
            for match in pattern.finditer(content):
                name = match.group(1)
                if name in flags:
                    flags[name] = FeatureFlag(
                        name=flags[name].name,
                        file_path=flags[name].file_path,
                        usage_count=flags[name].usage_count + 1,
                    )
                else:
                    flags[name] = FeatureFlag(name=name, file_path=rel, usage_count=1)

    inventory = FeatureFlagInventory(flags=list(flags.values()))
    dossier_manager.write_section("feature_flags", inventory)
    dossier_manager.mark_agent_complete(AGENT_NAME)
    logger.info("FeatureFlagMapper: %d flags detected", len(flags))

"""DossierManager — thread-safe operations on the shared Dossier blackboard."""

import threading
from typing import Any, Optional

from src.dossier.schema import (
    ConflictAnalysis,
    Dossier,
    SecurityFinding,
    Severity,
    TechnicalDebtItem,
)


class DossierManager:
    """Thread-safe wrapper around a Dossier instance.

    All write operations use a lock so concurrent facet agents can safely
    append findings without race conditions.
    """

    def __init__(self, dossier: Optional[Dossier] = None) -> None:
        self._dossier = dossier or Dossier()
        self._lock = threading.Lock()

    @property
    def dossier(self) -> Dossier:
        return self._dossier

    # ─── Write operations ────────────────────────────────────────────────────

    def write_security_finding(self, finding: SecurityFinding) -> None:
        with self._lock:
            self._dossier.security.append(finding)
            # Emit tags so downstream routing can pick up specialist agents
            for tag in finding.tags:
                if tag not in self._dossier.emitted_tags:
                    self._dossier.emitted_tags.append(tag)

    def write_conflict(self, conflict: ConflictAnalysis) -> None:
        with self._lock:
            self._dossier.conflicts.append(conflict)

    def write_section(self, section: str, value: Any) -> None:
        """Set a top-level Dossier section by name (e.g. 'architecture')."""
        with self._lock:
            if not hasattr(self._dossier, section):
                raise ValueError(f"Unknown Dossier section: {section!r}")
            object.__setattr__(self._dossier, section, value)

    def mark_agent_complete(self, agent_name: str) -> None:
        with self._lock:
            if agent_name not in self._dossier.agents_completed:
                self._dossier.agents_completed.append(agent_name)

    def mark_agent_failed(self, agent_name: str) -> None:
        with self._lock:
            if agent_name not in self._dossier.agents_failed:
                self._dossier.agents_failed.append(agent_name)

    # ─── Query operations ────────────────────────────────────────────────────

    def query_findings(
        self,
        section: str = "security",
        module: Optional[str] = None,
        severity: Optional[Severity] = None,
    ) -> list[Any]:
        """Query findings from a Dossier section with optional filters.

        Args:
            section: Dossier section name (default: "security").
            module: Filter by related_modules membership.
            severity: Filter by minimum severity level.

        Returns:
            Filtered list of findings from the requested section.
        """
        items = getattr(self._dossier, section, None)
        if items is None:
            return []
        if not isinstance(items, list):
            return [items]

        # Apply filters
        results = items
        if module is not None:
            results = [
                f for f in results
                if hasattr(f, "related_modules") and module in f.related_modules
            ]
        if severity is not None:
            severity_order = [s.value for s in Severity]
            min_idx = severity_order.index(severity.value)
            results = [
                f for f in results
                if hasattr(f, "severity") and severity_order.index(f.severity.value) <= min_idx
            ]
        return results

    def get_section(self, section: str) -> Any:
        """Return the full value of a Dossier section."""
        return getattr(self._dossier, section, None)

    def has_tag(self, tag: str) -> bool:
        return tag in self._dossier.emitted_tags

    def clear(self) -> None:
        """Reset the Dossier to empty state (useful for testing)."""
        with self._lock:
            self._dossier = Dossier()

"""Capability primitives used by ReAct and single-pass agents.

Each primitive is a callable tool with typed inputs/outputs.
These are registered as LangGraph tool nodes.
"""

from __future__ import annotations

import logging
import re
from pathlib import Path
from typing import Any, Optional

from src.dossier.manager import DossierManager
from src.dossier.schema import SecurityFinding, Severity

logger = logging.getLogger(__name__)


def read_file(file_path: str, max_lines: int = 200) -> str:
    """Read a source file and return its contents (up to max_lines).

    Args:
        file_path: Absolute or relative path to the file.
        max_lines: Maximum lines to return (avoids flooding context).

    Returns:
        File contents as string, or error message.
    """
    try:
        lines = Path(file_path).read_text(errors="replace").splitlines()
        if len(lines) > max_lines:
            return "\n".join(lines[:max_lines]) + f"\n... [{len(lines) - max_lines} more lines truncated]"
        return "\n".join(lines)
    except OSError as exc:
        return f"ERROR: Cannot read {file_path}: {exc}"


def search_code(
    repo_path: str,
    pattern: str,
    extensions: list[str] | None = None,
    max_results: int = 20,
) -> list[dict[str, Any]]:
    """Search source files for a regex pattern.

    Args:
        repo_path: Repository root directory.
        pattern: Regex pattern to search for.
        extensions: File extensions to search (e.g. [".py", ".ts"]).
        max_results: Maximum number of matches to return.

    Returns:
        List of dicts with keys: file, line_number, line_content.
    """
    root = Path(repo_path)
    try:
        regex = re.compile(pattern, re.IGNORECASE)
    except re.error as exc:
        logger.warning("Invalid regex %r: %s", pattern, exc)
        return []

    results: list[dict[str, Any]] = []
    skip_dirs = {".git", "node_modules", "__pycache__", ".venv", "dist", "build"}

    for file_path in root.rglob("*"):
        if len(results) >= max_results:
            break
        if not file_path.is_file():
            continue
        if any(skip in file_path.parts for skip in skip_dirs):
            continue
        if extensions and file_path.suffix.lower() not in extensions:
            continue
        try:
            for i, line in enumerate(file_path.read_text(errors="replace").splitlines(), 1):
                if regex.search(line):
                    results.append({
                        "file": str(file_path.relative_to(root)),
                        "line_number": i,
                        "line_content": line.strip(),
                    })
                    if len(results) >= max_results:
                        break
        except OSError:
            pass
    return results


def query_dossier(dossier_manager: DossierManager, section: str, query: Optional[str] = None) -> Any:
    """Read a section of the Dossier.

    Args:
        dossier_manager: The shared DossierManager.
        section: Section name (e.g. "security", "dependencies").
        query: Optional filter string (matched against descriptions).

    Returns:
        Section value, filtered if query provided.
    """
    value = dossier_manager.get_section(section)
    if value is None:
        return None
    if query and isinstance(value, list):
        query_lower = query.lower()
        return [
            item for item in value
            if query_lower in str(getattr(item, "description", "") or "").lower()
        ]
    return value


def write_finding(dossier_manager: DossierManager, finding: SecurityFinding) -> str:
    """Append a SecurityFinding to the Dossier.

    Args:
        dossier_manager: The shared DossierManager.
        finding: The SecurityFinding to write.

    Returns:
        "OK: <finding.id>" on success.
    """
    dossier_manager.write_security_finding(finding)
    return f"OK: {finding.id}"


def parse_ast(file_path: str) -> dict[str, Any]:
    """Return a structural summary of a Python or TypeScript file via the parser.

    Args:
        file_path: Absolute path to the source file.

    Returns:
        Dict with 'entities' list (name, type, line).
    """
    from src.parsers import get_parser
    from src.parsers.base import UnsupportedLanguageError

    ext = Path(file_path).suffix.lower()
    try:
        parser = get_parser(ext)
        entities = parser.parse_file(file_path)
        return {
            "entities": [
                {"name": e.name, "type": e.entity_type, "line": e.line_start}
                for e in entities
            ]
        }
    except UnsupportedLanguageError:
        return {"entities": [], "error": f"Unsupported extension {ext}"}
    except Exception as exc:
        return {"entities": [], "error": str(exc)}

"""ConflictSynthesizer — identifies contradictions between facet findings.

Per Constitution Principle II: NEVER resolves conflicts or picks winners.
Produces ConflictAnalysis objects with developer questions only.
"""

import json
import logging

from src.dossier.manager import DossierManager
from src.dossier.schema import ConflictAnalysis
from src.llm.client import chat

logger = logging.getLogger(__name__)

AGENT_NAME = "conflict_synthesizer"

_CONFLICT_CHECKS = [
    {
        "facet_a": "architecture",
        "facet_b": "dependencies",
        "prompt_fragment": "Check if the architectural style claimed by ArchitecturalClassifier is consistent with the dependency list.",
    },
    {
        "facet_a": "security",
        "facet_b": "ci_pipeline",
        "prompt_fragment": "Check if security findings are contradicted by CI pipeline security steps (e.g., SAST/DAST steps).",
    },
    {
        "facet_a": "observability",
        "facet_b": "error_resilience",
        "prompt_fragment": "Check if the observability profile matches the error resilience profile (e.g., good observability but many silent failures).",
    },
]


def run(dossier_manager: DossierManager) -> None:
    """Identify contradictions between facet findings."""
    conflicts_written = 0

    for check in _CONFLICT_CHECKS:
        section_a = dossier_manager.get_section(check["facet_a"])
        section_b = dossier_manager.get_section(check["facet_b"])

        if section_a is None or section_b is None:
            continue

        # Convert to string for LLM
        def _serialize(obj):
            if obj is None:
                return "null"
            try:
                return obj.model_dump_json(indent=2)
            except AttributeError:
                return json.dumps(str(obj)[:500])

        prompt = f"""You are ConflictSynthesizer. {check['prompt_fragment']}

{check['facet_a']} findings:
{_serialize(section_a)[:800]}

{check['facet_b']} findings:
{_serialize(section_b)[:800]}

IMPORTANT RULES:
- Do NOT pick a winner or say one finding is "correct"
- Do NOT resolve the conflict
- Do generate neutral developer questions

If you detect a genuine contradiction, return JSON:
{{
  "conflict_detected": true,
  "finding_a": "<what facet A claims>",
  "finding_b": "<what facet B claims>",
  "why_both_coexist": "<neutral explanation>",
  "developer_questions": ["<question>", ...]
}}

If no contradiction, return:
{{"conflict_detected": false}}"""

        try:
            response = chat(messages=[{"role": "user", "content": prompt}])
            data = json.loads(response)
        except Exception as exc:
            logger.debug("ConflictSynthesizer check skipped (%s): %s", check["facet_a"], exc)
            continue

        if data.get("conflict_detected"):
            conflict = ConflictAnalysis(
                facet_a=check["facet_a"],
                finding_a=data.get("finding_a", ""),
                facet_b=check["facet_b"],
                finding_b=data.get("finding_b", ""),
                why_both_coexist=data.get("why_both_coexist", ""),
                developer_questions=data.get("developer_questions", []),
            )
            dossier_manager.write_conflict(conflict)
            conflicts_written += 1
            logger.info(
                "Conflict detected: %s vs %s",
                check["facet_a"], check["facet_b"],
            )

    dossier_manager.mark_agent_complete(AGENT_NAME)
    logger.info("ConflictSynthesizer: %d conflicts written", conflicts_written)

"""Builders for special wiki pages: getting_started, function_index, glossary, api_reference."""

import json
import logging
import re
from pathlib import Path
from typing import Any

from src.llm.client import chat
from src.parsers.base import ParsedEntity

logger = logging.getLogger(__name__)


def build_getting_started(
    repo_name: str,
    repo_path: str,
    fingerprint_dict: dict,
) -> dict[str, Any]:
    """Extract prerequisites and setup steps from README and config files (FR-007)."""
    # Try reading README first
    readme_content = ""
    for readme in ["README.md", "README.rst", "README.txt", "README"]:
        readme_path = Path(repo_path) / readme
        if readme_path.exists():
            try:
                readme_content = readme_path.read_text(errors="replace")[:4000]
                break
            except OSError:
                pass

    if not readme_content:
        readme_content = f"Repository: {repo_name}\nLanguage: {fingerprint_dict.get('primary_language', 'unknown')}"

    prompt = f"""Extract structured getting-started information from this README.

{readme_content}

Return JSON only:
{{
  "prerequisites": [{{"name": "<tool>", "version": "<version or any>", "description": "<why needed>"}}],
  "setup_steps": [{{"step": <number>, "title": "<title>", "command": "<command or null>", "description": "<desc>"}}],
  "configuration": [{{"key": "<env var>", "description": "<what it does>", "required": <bool>}}],
  "quick_links": [{{"label": "<label>", "url": "<url or path>"}}]
}}"""

    try:
        response = chat(messages=[{"role": "user", "content": prompt}])
        content = json.loads(response)
    except Exception as exc:
        logger.warning("Getting started page build failed: %s", exc)
        content = {
            "prerequisites": [],
            "setup_steps": [{"step": 1, "title": "Clone repository", "command": f"git clone <url>", "description": ""}],
            "configuration": [],
            "quick_links": [],
        }

    content["page_type"] = "getting_started"
    return content


def build_function_index(entities: list[ParsedEntity]) -> dict[str, Any]:
    """Build an alphabetical index of all public code entities (FR-008)."""
    public = [
        e for e in entities
        if not e.name.startswith("_") and e.entity_type in ("function", "class", "method")
    ]
    public.sort(key=lambda e: e.name.lower())

    # Group by first letter
    index: dict[str, list[dict]] = {}
    for entity in public:
        letter = entity.name[0].upper() if entity.name else "#"
        index.setdefault(letter, []).append({
            "name": entity.name,
            "qualified_name": entity.qualified_name,
            "type": entity.entity_type,
            "file": entity.file_path,
            "line": entity.line_start,
            "signature": entity.signature,
            "summary": (entity.docstring or "").split("\n")[0][:100] if entity.docstring else "",
        })

    return {
        "page_type": "function_index",
        "total_count": len(public),
        "index": index,
    }


def build_glossary(entities: list[ParsedEntity], repo_path: str) -> dict[str, Any]:
    """Extract domain terms from docstrings and comments (FR-009)."""
    # Collect all docstrings
    all_docs = " ".join(
        e.docstring for e in entities if e.docstring
    )[:6000]

    if not all_docs.strip():
        return {"page_type": "glossary", "terms": [], "total_count": 0}

    prompt = f"""Extract a glossary of domain-specific terms from these code docstrings.

{all_docs}

Return JSON only:
{{
  "terms": [
    {{
      "term": "<term>",
      "type": "concept|pattern|acronym|entity",
      "definition": "<1-2 sentence definition>",
      "related_terms": ["<term>", ...]
    }},
    ...
  ]
}}

Include: domain concepts, business terms, technical patterns, acronyms.
Exclude: generic programming terms (function, class, method, etc.)."""

    try:
        response = chat(messages=[{"role": "user", "content": prompt}])
        data = json.loads(response)
        terms = data.get("terms", [])
    except Exception as exc:
        logger.warning("Glossary build failed: %s", exc)
        terms = []

    # Sort alphabetically
    terms.sort(key=lambda t: t.get("term", "").lower())

    return {
        "page_type": "glossary",
        "terms": terms,
        "total_count": len(terms),
    }


def build_api_reference(entities: list[ParsedEntity]) -> dict[str, Any]:
    """Build alphabetical API reference index (FR-008)."""
    api_entities = [
        e for e in entities
        if not e.name.startswith("_") and e.entity_type in ("function", "class")
    ]
    api_entities.sort(key=lambda e: e.name.lower())

    # Group by first letter
    index: dict[str, list[dict]] = {}
    for entity in api_entities:
        letter = entity.name[0].upper() if entity.name else "#"
        index.setdefault(letter, []).append({
            "name": entity.name,
            "qualified_name": entity.qualified_name,
            "type": entity.entity_type,
            "file": entity.file_path,
            "line": entity.line_start,
            "signature": entity.signature,
            "description": (entity.docstring or "").split("\n")[0][:200] if entity.docstring else "",
            "visibility": "public",
        })

    return {
        "page_type": "api_reference",
        "total_count": len(api_entities),
        "index": index,
    }

"""Diagram data generator — T098.

Queries Neo4j for module relationships, dependency graphs, and call chains,
outputting structured data for frontend rendering via the diagrams endpoint.
"""

import logging
from typing import Any

from sqlalchemy.orm import Session

from src.models.code_entity import CodeEntity, Module
from src.models.wiki import Wiki
from src.storage import graph_db

logger = logging.getLogger(__name__)

# Node colours for consistent visual identity across diagram types
_MODULE_COLORS = ['purple', 'cyan', 'pink', 'green', 'amber']


def build_diagrams(session: Session, wiki: Wiki) -> dict[str, Any]:
    """Build all diagram data for a repository wiki.

    Returns:
        Dict with keys: architecture, dependency_graph, module_relationships.
        Each value contains nodes (list) and edges (list).
    """
    modules = session.query(Module).filter_by(wiki_id=wiki.id).all()
    module_ids = [m.id for m in modules]

    architecture = _build_architecture_diagram(session, wiki, modules)
    dependency_graph = _build_dependency_graph(session, wiki, modules)
    module_relationships = _build_module_relationships(modules, module_ids)

    return {
        "architecture": architecture,
        "dependency_graph": dependency_graph,
        "module_relationships": module_relationships,
    }


def _build_architecture_diagram(
    session: Session, wiki: Wiki, modules: list[Module]
) -> dict[str, Any]:
    """Architecture overview — groups modules into logical tiers.

    Nodes are coloured by tier (frontend, api, services, data).
    """
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []

    for i, module in enumerate(modules[:20]):  # cap at 20 for readability
        color = _MODULE_COLORS[i % len(_MODULE_COLORS)]
        icon = _module_icon(module.name)
        tier = _classify_tier(module.name, module.file_paths or [])

        nodes.append({
            "id": module.id,
            "label": module.name,
            "sublabel": (module.file_paths or [''])[0],
            "color": color,
            "icon": icon,
            "tier": tier,
            "file_count": module.file_count,
            "slug": module.slug,
        })

    # Add edges based on module dependency_module_ids (PostgreSQL-stored)
    node_ids = {n["id"] for n in nodes}
    for module in modules:
        for dep_id in (module.dependency_module_ids or []):
            if dep_id in node_ids and dep_id != module.id:
                edges.append({
                    "from": module.id,
                    "to": dep_id,
                    "label": "depends on",
                })

    return {"nodes": nodes, "edges": edges}


def _build_dependency_graph(
    session: Session, wiki: Wiki, modules: list[Module]
) -> dict[str, Any]:
    """Dependency graph — circular bubble nodes from Neo4j inter-module calls."""
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []

    module_ids = [m.id for m in modules]
    id_to_module = {m.id: m for m in modules}

    # Query Neo4j for inter-module relationships
    neo_edges: list[dict[str, Any]] = []
    try:
        neo_edges = graph_db.get_module_relationships(module_ids)
    except Exception as exc:
        logger.warning("Neo4j module relationship query failed: %s", exc)

    # Build node set from modules with call counts
    call_counts: dict[str, int] = {}
    for edge in neo_edges:
        from_id = edge.get("from_module", "")
        call_counts[from_id] = call_counts.get(from_id, 0) + int(edge.get("weight", 1))

    for i, module in enumerate(modules[:16]):
        color = _MODULE_COLORS[i % len(_MODULE_COLORS)]
        nodes.append({
            "id": module.id,
            "label": module.name,
            "color": color,
            "call_count": call_counts.get(module.id, 0),
            "slug": module.slug,
        })

    # Edges from Neo4j
    node_ids = {n["id"] for n in nodes}
    for edge in neo_edges:
        from_id = edge.get("from_module", "")
        to_id = edge.get("to_module", "")
        if from_id in node_ids and to_id in node_ids and from_id != to_id:
            edges.append({
                "from": from_id,
                "to": to_id,
                "rel_type": edge.get("rel_type", "CALLS"),
                "weight": edge.get("weight", 1),
            })

    return {"nodes": nodes, "edges": edges}


def _build_module_relationships(
    modules: list[Module],
    module_ids: list[str],
) -> dict[str, Any]:
    """Module relationship grid — shows which modules depend on which others."""
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []

    for i, module in enumerate(modules[:12]):
        color = _MODULE_COLORS[i % len(_MODULE_COLORS)]
        nodes.append({
            "id": module.id,
            "label": module.name,
            "sublabel": f"{module.file_count} files",
            "color": color,
            "slug": module.slug,
        })

    node_ids = {n["id"] for n in nodes}
    for module in modules:
        for dep_id in (module.dependency_module_ids or []):
            if dep_id in node_ids and dep_id != module.id:
                edges.append({
                    "from": module.id,
                    "to": dep_id,
                    "label": "uses",
                })

    return {"nodes": nodes, "edges": edges}


def _classify_tier(name: str, file_paths: list[str]) -> str:
    """Classify a module into a rough architectural tier."""
    name_lower = name.lower()
    paths = " ".join(file_paths).lower()

    if any(k in name_lower for k in ["ui", "frontend", "view", "component", "page", "web"]):
        return "frontend"
    if any(k in name_lower for k in ["api", "route", "endpoint", "handler", "controller"]):
        return "api"
    if any(k in name_lower for k in ["db", "database", "model", "repo", "store", "cache"]):
        return "data"
    if any(k in name_lower for k in ["test", "spec"]):
        return "test"
    return "service"


def _module_icon(name: str) -> str:
    """Return an emoji icon for a module based on its name."""
    name_lower = name.lower()
    if any(k in name_lower for k in ["auth", "login", "security", "jwt"]):
        return "🔐"
    if any(k in name_lower for k in ["api", "route", "endpoint"]):
        return "🔌"
    if any(k in name_lower for k in ["db", "database", "model", "store"]):
        return "🗄️"
    if any(k in name_lower for k in ["chat", "message", "ai", "llm"]):
        return "💬"
    if any(k in name_lower for k in ["search", "index", "query"]):
        return "🔍"
    if any(k in name_lower for k in ["wiki", "doc", "page"]):
        return "📄"
    if any(k in name_lower for k in ["test", "spec"]):
        return "🧪"
    if any(k in name_lower for k in ["util", "helper", "common"]):
        return "🔧"
    return "📦"

"""Module page builder — creates module documentation pages (page_type=module)."""

import re
from typing import Any

from src.parsers.base import ParsedEntity


def slugify(name: str) -> str:
    """Convert module name to URL-safe slug."""
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")


def build_module_page(
    module_name: str,
    wiki_content: dict[str, Any],  # output from wiki orchestrator
    entities: list[ParsedEntity],
    file_paths: list[str],
    dependencies_modules: list[str] = None,
    commit_hash: str | None = None,
) -> dict[str, Any]:
    """Build structured module page content (8 sections per spec FR-010).

    Sections: overview, location, how_it_works, key_components, dependencies,
              configuration, related_pages, known_issues
    """
    # Extract public entities for key components section
    public_entities = [
        e for e in entities
        if not e.name.startswith("_") and e.entity_type in ("function", "class", "method")
    ][:20]

    return {
        "page_type": "module",
        "overview": {
            "purpose": wiki_content.get("purpose", ""),
            "design_patterns": wiki_content.get("design_patterns", []),
            "data_flow": wiki_content.get("data_flow", ""),
        },
        "location": {
            "files": file_paths,
            "file_count": len(file_paths),
            "primary_file": file_paths[0] if file_paths else None,
        },
        "how_it_works": wiki_content.get("data_flow", ""),
        "key_components": wiki_content.get("key_components", [
            {"name": e.name, "role": e.docstring or e.signature or ""}
            for e in public_entities[:8]
        ]),
        "dependencies": wiki_content.get("dependencies", {"internal": [], "external": []}),
        "configuration": wiki_content.get("configuration", ""),
        "related_pages": [
            {"name": m, "slug": slugify(m)}
            for m in wiki_content.get("related_modules", [])
        ],
        "known_issues": wiki_content.get("gotchas", []),
        "security_notes": wiki_content.get("security_notes", ""),
        "commit_hash": commit_hash,
    }


def build_dashboard_page(
    repo_name: str,
    modules: list[dict],
) -> dict[str, Any]:
    """Build a high-level dashboard/index page for module navigation."""
    return {
        "page_type": "home",
        "title": f"{repo_name} — Module Overview",
        "modules": modules,
        "module_count": len(modules),
    }

/**
 * TypeScript Compiler API extractor.
 * Called from Python via subprocess; reads a .ts/.tsx/.js/.jsx file,
 * then writes JSON to stdout with entities, imports, and call edges.
 *
 * Usage: node extractor.js <file_path>
 */

"use strict";

const ts = require("typescript");
const path = require("path");
const fs = require("fs");

const filePath = process.argv[2];
if (!filePath) {
  process.stderr.write("Usage: node extractor.js <file_path>\n");
  process.exit(1);
}

const absolutePath = path.resolve(filePath);
const source = fs.readFileSync(absolutePath, "utf8");

const compilerOptions = {
  target: ts.ScriptTarget.ESNext,
  module: ts.ModuleKind.CommonJS,
  strict: true,
  esModuleInterop: true,
  allowJs: true,
  jsx: ts.JsxEmit.React,
  allowSyntheticDefaultImports: true,
};

const program = ts.createProgram([absolutePath], compilerOptions);
const sourceFile = program.getSourceFile(absolutePath);
const checker = program.getTypeChecker();

if (!sourceFile) {
  process.stderr.write(`Could not parse: ${absolutePath}\n`);
  process.exit(1);
}

const entities = [];
const imports = [];
const callEdges = [];
const lines = source.split("\n");

function getLineCol(pos) {
  const lc = sourceFile.getLineAndCharacterOfPosition(pos);
  return { line: lc.line + 1, col: lc.character };
}

function getDocstring(node) {
  const ranges = ts.getLeadingCommentRanges(source, node.getFullStart());
  if (!ranges || ranges.length === 0) return null;
  const last = ranges[ranges.length - 1];
  const text = source.slice(last.pos, last.end);
  if (text.startsWith("/**")) {
    // Strip /** ... */ wrapper and leading * on each line
    return text
      .replace(/^\/\*\*/, "")
      .replace(/\*\/$/, "")
      .split("\n")
      .map((l) => l.replace(/^\s*\*\s?/, ""))
      .join("\n")
      .trim();
  }
  return null;
}

function getTypeStr(node) {
  try {
    const type = checker.getTypeAtLocation(node);
    return checker.typeToString(type);
  } catch {
    return null;
  }
}

function buildSignature(node) {
  // Use printer to produce a clean signature string
  const printer = ts.createPrinter({ removeComments: true });
  try {
    // Print just the declaration without the body
    if (ts.isFunctionDeclaration(node) || ts.isMethodDeclaration(node) || ts.isArrowFunction(node)) {
      const params = node.parameters
        .map((p) => {
          const name = p.name.getText(sourceFile);
          const typeStr = p.type ? p.type.getText(sourceFile) : null;
          const opt = p.questionToken ? "?" : "";
          const def = p.initializer ? ` = ${p.initializer.getText(sourceFile)}` : "";
          return typeStr ? `${name}${opt}: ${typeStr}${def}` : `${name}${opt}${def}`;
        })
        .join(", ");
      const ret = node.type ? `: ${node.type.getText(sourceFile)}` : "";
      const name =
        ts.isFunctionDeclaration(node) && node.name
          ? node.name.getText(sourceFile)
          : ts.isMethodDeclaration(node) && node.name
          ? node.name.getText(sourceFile)
          : "(anonymous)";
      const async = node.modifiers?.some((m) => m.kind === ts.SyntaxKind.AsyncKeyword) ? "async " : "";
      return `${async}function ${name}(${params})${ret}`;
    }
  } catch {
    // fall through
  }
  return null;
}

function extractCalls(node, callerName) {
  ts.forEachChild(node, function walk(child) {
    if (ts.isCallExpression(child)) {
      let callee = "";
      if (ts.isIdentifier(child.expression)) {
        callee = child.expression.text;
      } else if (ts.isPropertyAccessExpression(child.expression)) {
        callee = child.expression.getText(sourceFile);
      }
      if (callee) {
        callEdges.push({ caller: callerName, callee });
      }
    }
    ts.forEachChild(child, walk);
  });
}

const moduleName = path
  .relative(process.cwd(), absolutePath)
  .replace(/\\/g, "/")
  .replace(/\.(ts|tsx|js|jsx)$/, "")
  .replace(/\//g, ".");

function visitNode(node, parentClass) {
  // Import declarations
  if (ts.isImportDeclaration(node)) {
    const moduleSpec = node.moduleSpecifier.getText(sourceFile).replace(/['"]/g, "");
    const clause = node.importClause;
    if (clause) {
      if (clause.name) {
        imports.push({ imported_name: moduleSpec + ".default", source_file: absolutePath });
      }
      if (clause.namedBindings) {
        if (ts.isNamedImports(clause.namedBindings)) {
          clause.namedBindings.elements.forEach((el) => {
            imports.push({
              imported_name: `${moduleSpec}.${el.name.text}`,
              source_file: absolutePath,
            });
          });
        } else if (ts.isNamespaceImport(clause.namedBindings)) {
          imports.push({ imported_name: moduleSpec, source_file: absolutePath });
        }
      }
    } else {
      imports.push({ imported_name: moduleSpec, source_file: absolutePath });
    }
  }

  // Class declarations
  if (ts.isClassDeclaration(node) && node.name) {
    const className = node.name.text;
    const qname = `${moduleName}.${className}`;
    const startLine = getLineCol(node.getStart(sourceFile)).line;
    const endLine = getLineCol(node.getEnd()).line;
    const bases = [];
    if (node.heritageClauses) {
      node.heritageClauses.forEach((hc) => {
        hc.types.forEach((t) => bases.push(t.expression.getText(sourceFile)));
      });
    }
    entities.push({
      name: className,
      qualified_name: qname,
      entity_type: "class",
      file_path: absolutePath,
      line_start: startLine,
      line_end: endLine,
      docstring: getDocstring(node),
      entity_metadata: { bases, is_exported: !!(ts.getCombinedModifierFlags(node) & ts.ModifierFlags.Export) },
    });

    // Visit class members
    node.members.forEach((member) => {
      if (ts.isMethodDeclaration(member) && member.name) {
        const methodName = member.name.getText(sourceFile);
        const mQname = `${qname}.${methodName}`;
        const mStart = getLineCol(member.getStart(sourceFile)).line;
        const mEnd = getLineCol(member.getEnd()).line;
        extractCalls(member, mQname);
        entities.push({
          name: methodName,
          qualified_name: mQname,
          entity_type: "method",
          file_path: absolutePath,
          line_start: mStart,
          line_end: mEnd,
          signature: buildSignature(member),
          docstring: getDocstring(member),
          entity_metadata: {
            class: className,
            is_static: !!(ts.getCombinedModifierFlags(member) & ts.ModifierFlags.Static),
            is_async: !!(ts.getCombinedModifierFlags(member) & ts.ModifierFlags.Async),
            is_exported: !!(ts.getCombinedModifierFlags(member) & ts.ModifierFlags.Export),
          },
        });
      } else if (ts.isPropertyDeclaration(member) && member.name) {
        const propName = member.name.getText(sourceFile);
        const pStart = getLineCol(member.getStart(sourceFile)).line;
        entities.push({
          name: propName,
          qualified_name: `${qname}.${propName}`,
          entity_type: "variable",
          file_path: absolutePath,
          line_start: pStart,
          line_end: pStart,
          entity_metadata: { class: className, type: member.type ? member.type.getText(sourceFile) : null },
        });
      }
    });
  }

  // Function declarations
  if (ts.isFunctionDeclaration(node) && node.name && !parentClass) {
    const fnName = node.name.text;
    const qname = `${moduleName}.${fnName}`;
    const startLine = getLineCol(node.getStart(sourceFile)).line;
    const endLine = getLineCol(node.getEnd()).line;
    extractCalls(node, qname);
    entities.push({
      name: fnName,
      qualified_name: qname,
      entity_type: "function",
      file_path: absolutePath,
      line_start: startLine,
      line_end: endLine,
      signature: buildSignature(node),
      docstring: getDocstring(node),
      entity_metadata: {
        is_async: !!(ts.getCombinedModifierFlags(node) & ts.ModifierFlags.Async),
        is_exported: !!(ts.getCombinedModifierFlags(node) & ts.ModifierFlags.Export),
      },
    });
  }

  // Variable statements (const foo = () => ...)
  if (ts.isVariableStatement(node) && !parentClass) {
    node.declarationList.declarations.forEach((decl) => {
      if (ts.isIdentifier(decl.name) && decl.initializer) {
        const varName = decl.name.text;
        const qname = `${moduleName}.${varName}`;
        const startLine = getLineCol(decl.getStart(sourceFile)).line;

        if (ts.isArrowFunction(decl.initializer) || ts.isFunctionExpression(decl.initializer)) {
          extractCalls(decl.initializer, qname);
          entities.push({
            name: varName,
            qualified_name: qname,
            entity_type: "function",
            file_path: absolutePath,
            line_start: startLine,
            line_end: getLineCol(decl.getEnd()).line,
            docstring: getDocstring(node),
            entity_metadata: {
              is_arrow: ts.isArrowFunction(decl.initializer),
              is_exported: !!(ts.getCombinedModifierFlags(node) & ts.ModifierFlags.Export),
            },
          });
        } else {
          entities.push({
            name: varName,
            qualified_name: qname,
            entity_type: "variable",
            file_path: absolutePath,
            line_start: startLine,
            line_end: startLine,
            entity_metadata: {
              type: getTypeStr(decl),
              is_exported: !!(ts.getCombinedModifierFlags(node) & ts.ModifierFlags.Export),
            },
          });
        }
      }
    });
  }

  // Interface declarations
  if (ts.isInterfaceDeclaration(node)) {
    const ifName = node.name.text;
    const qname = `${moduleName}.${ifName}`;
    const startLine = getLineCol(node.getStart(sourceFile)).line;
    entities.push({
      name: ifName,
      qualified_name: qname,
      entity_type: "class",  // treat interface as class-like
      file_path: absolutePath,
      line_start: startLine,
      line_end: getLineCol(node.getEnd()).line,
      docstring: getDocstring(node),
      entity_metadata: {
        is_interface: true,
        is_exported: !!(ts.getCombinedModifierFlags(node) & ts.ModifierFlags.Export),
      },
    });
  }

  ts.forEachChild(node, (child) => visitNode(child, null));
}

ts.forEachChild(sourceFile, (node) => visitNode(node, null));

// Add module-level entity
entities.unshift({
  name: path.basename(absolutePath, path.extname(absolutePath)),
  qualified_name: moduleName,
  entity_type: "module",
  file_path: absolutePath,
  line_start: 1,
  line_end: lines.length,
  entity_metadata: {},
});

process.stdout.write(JSON.stringify({ entities, imports, call_edges: callEdges }, null, 0));

def _get_or_create_wiki(session: Session, repository_id: str) -> str | None:
    wiki = session.query(Wiki).filter_by(repository_id=repository_id).first()
    if not wiki:
        wiki = Wiki(repository_id=repository_id)
        session.add(wiki)
        session.flush()
    return str(wiki.id)


def _write_neo4j(entities: list[ParsedEntity]) -> None:
    """Write all entities and relationships to Neo4j."""
    driver = graph_db.get_driver()
    for entity in entities:
        try:
            graph_db.create_code_entity_node(
                driver=driver,
                qualified_name=entity.qualified_name,
                entity_type=entity.entity_type,
                file_path=entity.file_path,
                line_start=entity.line_start,
            )
            for callee in entity.calls:
                graph_db.create_relationship(
                    driver=driver,
                    from_qualified_name=entity.qualified_name,
                    to_qualified_name=callee,
                    rel_type="CALLS",
                )
        except Exception as exc:
            logger.debug("Neo4j write failed for %s: %s", entity.qualified_name, exc)


